const fs=require('node:fs'),path=require('node:path'),http=require('node:http'),assert=require('node:assert/strict');
const {app,BrowserWindow,screen}=require('electron');
const config=JSON.parse(fs.readFileSync(process.argv[2],'utf8'));
app.setPath('userData',path.join(config.fixtureRoot,'profile'));app.on('window-all-closed',()=>{});
const {VoiceCompanion}=require(path.join(config.desktopRoot,'dist','main','voice-companion.js'));
let companion,server;
async function waitForFocus(window) {
  const deadline=Date.now()+2000;
  while(!window.isFocused() && Date.now()<deadline) await new Promise(resolve=>setTimeout(resolve,20));
  assert.equal(window.isFocused(),true,'closing voice returns focus so the main window can listen for the next clap');
}
app.whenReady().then(async()=>{
  server=http.createServer((_req,res)=>{res.setHeader('Content-Type','text/html');res.end('<html><title>Voice</title><body><script>window.opens=[];window.notices=[];voiceCompanion.onOpen(open=>opens.push(open));voiceCompanion.onNotification(notice=>notices.push(notice));</script></body></html>');});
  await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
  const origin=`http://127.0.0.1:${server.address().port}`;
  companion=new VoiceCompanion({dashboardUrl:()=>origin,allowed:{origins:new Set([origin])}});
  await companion.start();
  const voice=BrowserWindow.getAllWindows()[0];
  const host=new BrowserWindow({show:false,width:640,height:400});
  await host.loadURL(origin+'/host');host.show();host.focus();await waitForFocus(host);
  companion.notify({type:'success',message:'Queued before the voice renderer was ready'});
  assert.equal(await voice.webContents.executeJavaScript('notices.length'),0);
  assert.equal(await voice.webContents.executeJavaScript('voiceCompanion.ready()'),true);
  assert.equal(await voice.webContents.executeJavaScript('new Promise(r=>setTimeout(()=>r(notices[0].message),50))'),'Queued before the voice renderer was ready');
  const [width,height]=voice.getSize();
  const area=screen.getDisplayNearestPoint(screen.getCursorScreenPoint()).workArea;
  const scale=Math.min(1,area.width/800,area.height/480);
  assert.ok(Math.abs(width-Math.round(800*scale))<=1 && Math.abs(height-Math.round(480*scale))<=1, 'voice opens at four times the previous area and fits the display');
  assert.ok(Math.abs(width/height-400/240)<0.03, 'display scaling preserves the wide widget proportions');
  assert.equal(voice.isResizable(),false);assert.equal(voice.isMaximizable(),false);assert.equal(voice.isVisible(),false);
  assert.equal(await voice.webContents.executeJavaScript('voiceCompanion.state()'),false);
  await Promise.all([companion.launch('origin-chat-link'),companion.launch('origin-chat-link')]);assert.equal(BrowserWindow.getAllWindows().length,2);
  await waitForFocus(voice);
  assert.equal(voice.isVisible(),true);assert.equal(await voice.webContents.executeJavaScript('voiceCompanion.state()'),true);
  assert.equal(await voice.webContents.executeJavaScript('voiceCompanion.conversation()'),'origin-chat-link');
  const expandedBounds=voice.getBounds();
  const opensBeforeMinimize=await voice.webContents.executeJavaScript('opens.length');
  assert.equal(await voice.webContents.executeJavaScript('voiceCompanion.setMinimized(true)'),true);
  assert.deepEqual(voice.getSize(),[240,72]);
  assert.equal(voice.isVisible(),true);
  assert.equal(await voice.webContents.executeJavaScript('voiceCompanion.state()'),true);
  assert.equal(await voice.webContents.executeJavaScript('voiceCompanion.conversation()'),'origin-chat-link');
  assert.equal(await voice.webContents.executeJavaScript('opens.length'),opensBeforeMinimize,'minimizing does not close or restart the voice session');
  const miniBounds=voice.getBounds();
  assert.equal(miniBounds.x+miniBounds.width,expandedBounds.x+expandedBounds.width);
  assert.equal(miniBounds.y+miniBounds.height,expandedBounds.y+expandedBounds.height);
  assert.equal(await voice.webContents.executeJavaScript('voiceCompanion.setMinimized(false)'),false);
  assert.deepEqual(voice.getBounds(),expandedBounds);
  await voice.webContents.executeJavaScript('voiceCompanion.setMinimized(true)');
  await companion.launch('origin-chat-link');
  assert.deepEqual(voice.getBounds(),expandedBounds,'opening voice again restores the full panel');
  await host.webContents.executeJavaScript(`window.chatChannel=new BroadcastChannel('breadboard:voice-chat:origin-chat-link');chatChannel.onmessage=event=>{window.spokenTurn=event.data;chatChannel.postMessage({reply:'Same chat reply'});};void 0;`);
  const answer=await voice.webContents.executeJavaScript(`new Promise(resolve=>{const channel=new BroadcastChannel('breadboard:voice-chat:origin-chat-link');channel.onmessage=event=>{channel.close();resolve(event.data.reply);};channel.postMessage({text:'Continue our chat'});})`);
  assert.equal(answer,'Same chat reply');
  assert.deepEqual(await host.webContents.executeJavaScript('window.spokenTurn'),{text:'Continue our chat'});
  companion.notify({type:'success',message:'A test notification'});
  assert.equal(await voice.webContents.executeJavaScript('new Promise(r=>setTimeout(()=>r(notices.at(-1).message),50))'),'A test notification');
  await voice.webContents.executeJavaScript('voiceCompanion.setMinimized(true)');
  voice.close();assert.equal(voice.isDestroyed(),false);assert.equal(voice.isVisible(),false);
  assert.deepEqual(voice.getBounds(),expandedBounds,'closing a minimized session resets the next opening');
  await waitForFocus(host);
  assert.equal(await voice.webContents.executeJavaScript('voiceCompanion.state()'),false);
  assert.equal(await voice.webContents.executeJavaScript('voiceCompanion.conversation()'),null);
  assert.equal(await voice.webContents.executeJavaScript('voiceCompanion.open()'),true);assert.equal(voice.isVisible(),true);
  await waitForFocus(voice);
  await voice.webContents.executeJavaScript('voiceCompanion.close()');assert.equal(voice.isVisible(),false);
  await waitForFocus(host);
  const outsider=new BrowserWindow({show:false,webPreferences:{sandbox:true,contextIsolation:true,preload:path.join(config.desktopRoot,'dist','preload','voice-preload.js')}});
  await outsider.loadURL(origin+'/voice');assert.equal(await outsider.webContents.executeJavaScript('voiceCompanion.open()'),false);
  assert.equal(await outsider.webContents.executeJavaScript('voiceCompanion.setMinimized(true)'),false);
  assert.deepEqual(voice.getBounds(),expandedBounds,'another renderer cannot resize voice');
  assert.equal(voice.isVisible(),false);
  await companion.launch();await waitForFocus(voice);
  outsider.show();outsider.focus();await waitForFocus(outsider);
  await voice.webContents.executeJavaScript('voiceCompanion.close()');
  assert.equal(host.isFocused(),false,'closing an unfocused voice widget does not steal focus');
  assert.equal(outsider.isFocused(),true);outsider.destroy();host.destroy();
  companion.stop();assert.equal(BrowserWindow.getAllWindows().length,0);
  fs.writeFileSync(config.resultPath,JSON.stringify({ok:true}));server.close();app.exit(0);
}).catch(error=>{fs.writeFileSync(config.resultPath,JSON.stringify({ok:false,error:error.stack}));companion?.stop();server?.close();app.exit(1);});
